const CACHE='trazo-estudio-v2.6.0';const ASSETS=['./','./index.html','./style.css','./app.mjs','./bundled.mjs','./personal-letter.json','./maps.mjs','./maps-ui.mjs','./maps-storage.mjs','./maps.css','./core.mjs','./math.mjs','./document.mjs','./docs-ui.mjs','./model.mjs','./db.mjs','./worker.mjs','./exports.mjs','./vendor/opentype.mjs','./vendor/pdf-lib.min.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('trazo-estudio-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(url.origin!==location.origin||event.request.method!=='GET'||url.pathname.includes('/descargas/'))return;event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request)));});
